"""Validated vocabulary content generated by the operator's LLM command."""

import re
import unicodedata
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator


class GeneratedBankWord(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)

    word: str = Field(min_length=1, max_length=80)
    part_of_speech: Literal[
        "noun",
        "verb",
        "adjective",
        "adverb",
        "preposition",
        "conjunction",
        "pronoun",
        "determiner",
        "interjection",
    ]
    english_explanation: str = Field(min_length=1, max_length=1000)
    example_sentence: str = Field(min_length=1, max_length=1000)
    ipa: str = Field(min_length=3, max_length=120)

    @field_validator("word")
    @classmethod
    def english_word(cls, value: str) -> str:
        value = " ".join(unicodedata.normalize("NFKC", value).split())
        if not re.fullmatch(r"[A-Za-z]+(?:[-' ][A-Za-z]+){0,3}", value):
            raise ValueError("Use an English word or short everyday phrase")
        return value

    @field_validator("ipa")
    @classmethod
    def pronunciation(cls, value: str) -> str:
        if not re.fullmatch(r"/[^/\r\n]+/", value) or not value[1:-1].strip():
            raise ValueError("IPA must contain a pronunciation in slash notation")
        return value


class GeneratedBankBatch(BaseModel):
    model_config = ConfigDict(extra="forbid")
    words: list[GeneratedBankWord] = Field(min_length=1, max_length=20)
